// Every key here is generated by the test. None is committed.

type keyTestKey struct {
	name  string
	priv  crypto.Signer
	alg   string
	bits  int
	curve string
}

var (
	keyTestKeysOnce sync.Once
	keyTestKeysAll  []keyTestKey
)

func keyTestKeys(t testing.TB) []keyTestKey {
	t.Helper()
	keyTestKeysOnce.Do(func() {
		mustRSA := func(bits int) *rsa.PrivateKey {
			k, err := rsa.GenerateKey(rand.Reader, bits)
			if err != nil {
				panic(err)
			}
			return k
		}
		mustEC := func(c elliptic.Curve) *ecdsa.PrivateKey {
			k, err := ecdsa.GenerateKey(c, rand.Reader)
			if err != nil {
				panic(err)
			}
			return k
		}
		_, ed, err := ed25519.GenerateKey(rand.Reader)
		if err != nil {
			panic(err)
		}
		keyTestKeysAll = []keyTestKey{
			{"rsa2048", mustRSA(2048), "RSA", 2048, ""},
			{"rsa3072", mustRSA(3072), "RSA", 3072, ""},
			{"p256", mustEC(elliptic.P256()), "ECDSA", 256, "P-256"},
			{"p384", mustEC(elliptic.P384()), "ECDSA", 384, "P-384"},
			{"p521", mustEC(elliptic.P521()), "ECDSA", 521, "P-521"},
			{"ed25519", ed, "Ed25519", 256, ""},
		}
	})
	return keyTestKeysAll
}

// keyTestSecrets returns the private components of a key: what must never
// appear in a report.
func keyTestSecrets(t testing.TB, priv crypto.Signer) [][]byte {
	t.Helper()
	switch k := priv.(type) {
	case *rsa.PrivateKey:
		out := [][]byte{k.D.Bytes()}
		for _, p := range k.Primes {
			out = append(out, p.Bytes())
		}
		k.Precompute()
		if k.Precomputed.Dp != nil {
			out = append(out, k.Precomputed.Dp.Bytes(), k.Precomputed.Dq.Bytes(), k.Precomputed.Qinv.Bytes())
		}
		return out
	case *ecdsa.PrivateKey:
		e, err := k.ECDH()
		if err != nil {
			t.Fatal(err)
		}
		return [][]byte{e.Bytes()}
	case ed25519.PrivateKey:
		return [][]byte{k.Seed(), []byte(k)}
	}
	t.Fatalf("unknown key type %T", priv)
	return nil
}

func keyTestSPKIHash(t testing.TB, pub crypto.PublicKey) string {
	t.Helper()
	der, err := x509.MarshalPKIXPublicKey(pub)
	if err != nil {
		t.Fatal(err)
	}
	s := sha256.Sum256(der)
	return hex.EncodeToString(s[:])
}

// keyAssertNoLeak marshals v and fails if any 16-byte window of any secret
// appears in the JSON raw, as hex (either case) or as base64 (standard or
// URL alphabet, at every byte alignment).
func keyAssertNoLeak(t testing.TB, label string, v any, secrets ...[]byte) {
	t.Helper()
	blob, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("%s: marshal: %v", label, err)
	}
	if found := keyLeakIn(blob, secrets...); found != "" {
		t.Errorf("%s: private key material appears in the record (%s): %s", label, found, blob)
	}
	// JSON replaces invalid UTF-8, so binary copied raw into a string field
	// would be mangled in the blob above and slip past it. Check every string
	// in the value itself as well.
	var raw []byte
	keyCollectStrings(reflect.ValueOf(v), &raw)
	if found := keyLeakIn(raw, secrets...); found != "" {
		t.Errorf("%s: private key material appears in a string field (%s)", label, found)
	}
}

func keyCollectStrings(v reflect.Value, out *[]byte) {
	switch v.Kind() {
	case reflect.String:
		*out = append(append(*out, v.String()...), 0)
	case reflect.Pointer, reflect.Interface:
		if !v.IsNil() {
			keyCollectStrings(v.Elem(), out)
		}
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			keyCollectStrings(v.Field(i), out)
		}
	case reflect.Slice, reflect.Array:
		if v.Kind() == reflect.Slice && v.Type().Elem().Kind() == reflect.Uint8 {
			*out = append(append(*out, v.Bytes()...), 0)
			return
		}
		for i := 0; i < v.Len(); i++ {
			keyCollectStrings(v.Index(i), out)
		}
	case reflect.Map:
		it := v.MapRange()
		for it.Next() {
			keyCollectStrings(it.Key(), out)
			keyCollectStrings(it.Value(), out)
		}
	}
}

func keyLeakIn(blob []byte, secrets ...[]byte) string {
	const w = 16
	s := string(blob)
	for _, sec := range secrets {
		if len(sec) < w {
			continue
		}
		for i := 0; i+w <= len(sec); i++ {
			win := sec[i : i+w]
			if bytes.Contains(blob, win) {
				return "raw"
			}
			h := hex.EncodeToString(win)
			if strings.Contains(s, h) || strings.Contains(s, strings.ToUpper(h)) {
				return "hex"
			}
		}
		// A 16-byte window always contains 15 bytes aligned to a 3-byte group
		// of an encoding started at one of three offsets: 20 characters.
		for a := 0; a < 3 && a < len(sec); a++ {
			for _, enc := range []*base64.Encoding{base64.StdEncoding, base64.URLEncoding} {
				e := enc.EncodeToString(sec[a:])
				for j := 0; j+20 <= len(e)-4; j += 4 {
					if strings.Contains(s, e[j:j+20]) {
						return "base64"
					}
				}
			}
		}
	}
	return ""
}

// The guard itself must be able to fail, in each encoding.
func TestKeyLeakDetector_CatchesEachEncoding(t *testing.T) {
	sec := make([]byte, 64)
	_, _ = rand.Read(sec)
	cases := map[string]any{
		"hex":       map[string]string{"x": hex.EncodeToString(sec[5:30])},
		"HEX":       map[string]string{"x": strings.ToUpper(hex.EncodeToString(sec[1:40]))},
		"base64":    map[string]string{"x": base64.StdEncoding.EncodeToString(sec[7:40])},
		"base64url": map[string]string{"x": base64.RawURLEncoding.EncodeToString(sec[2:50])},
		"bytes":     map[string][]byte{"x": sec[3:30]}, // json encodes []byte as base64
	}
	for name, v := range cases {
		blob, _ := json.Marshal(v)
		if keyLeakIn(blob, sec) == "" {
			t.Errorf("%s: the leak detector missed a planted secret", name)
		}
	}
	blob, _ := json.Marshal(map[string]string{"x": hex.EncodeToString(sec[:15])})
	if got := keyLeakIn(blob, sec); got != "" {
		t.Errorf("a 15-byte fragment is below the window but was reported as %s", got)
	}
}

func keyTestPEM(label string, der []byte) []byte {
	return pem.EncodeToMemory(&pem.Block{Type: label, Bytes: der})
}

func keyTestSelfSigned(t testing.TB, priv crypto.Signer, cn string) []byte {
	t.Helper()
	tmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(0x1f2e3d),
		Subject:               pkix.Name{CommonName: cn, Organization: []string{"Example Org"}},
		NotBefore:             time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
		NotAfter:              time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC),
		DNSNames:              []string{"a.example.test", "b.example.test"},
		IsCA:                  true,
		BasicConstraintsValid: true,
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, priv.Public(), priv)
	if err != nil {
		t.Fatal(err)
	}
	return der
}

func TestParsePrivateKeyDER_GeneratedKeys(t *testing.T) {
	for _, tk := range keyTestKeys(t) {
		wantHash := keyTestSPKIHash(t, tk.priv.Public())
		pkcs8, err := x509.MarshalPKCS8PrivateKey(tk.priv)
		if err != nil {
			t.Fatal(err)
		}
		type form struct {
			name, format string
			der          []byte
		}
		forms := []form{{"pkcs8", KeyFormatPKCS8, pkcs8}}
		switch k := tk.priv.(type) {
		case *rsa.PrivateKey:
			forms = append(forms, form{"pkcs1", KeyFormatPKCS1, x509.MarshalPKCS1PrivateKey(k)})
		case *ecdsa.PrivateKey:
			sec1, err := x509.MarshalECPrivateKey(k)
			if err != nil {
				t.Fatal(err)
			}
			forms = append(forms, form{"sec1", KeyFormatSEC1, sec1})
		}
		for _, f := range forms {
			label := tk.name + "/" + f.name
			k, ok := ParsePrivateKeyDER(f.der)
			if !ok {
				t.Fatalf("%s: not recognised", label)
			}
			if k.Format != f.format || k.Algorithm != tk.alg || k.SizeBits != tk.bits || k.Curve != tk.curve {
				t.Errorf("%s: got format=%q alg=%q bits=%d curve=%q", label, k.Format, k.Algorithm, k.SizeBits, k.Curve)
			}
			if k.Encrypted == nil || *k.Encrypted {
				t.Errorf("%s: Encrypted = %v, want false", label, k.Encrypted)
			}
			if k.Protection != KeyProtectionFile {
				t.Errorf("%s: Protection = %q", label, k.Protection)
			}
			if k.PublicKeySHA256 != wantHash {
				t.Errorf("%s: PublicKeySHA256 = %q, want %q", label, k.PublicKeySHA256, wantHash)
			}
			if k.Unknown != "" {
				t.Errorf("%s: Unknown = %q for a fully readable key", label, k.Unknown)
			}
			keyAssertNoLeak(t, label, k, append(keyTestSecrets(t, tk.priv), f.der)...)
		}
	}
}

// The pairing rule: a key and the certificate made from it carry the same
// PublicKeySHA256, algorithm, size and curve.
func TestKeyAndCertificatePair(t *testing.T) {
	for _, tk := range keyTestKeys(t) {
		certDER := keyTestSelfSigned(t, tk.priv, "pair "+tk.name)
		c, err := ParseCertificateDER(certDER)
		if err != nil {
			t.Fatal(err)
		}
		pkcs8, _ := x509.MarshalPKCS8PrivateKey(tk.priv)
		k, _ := ParsePrivateKeyDER(pkcs8)
		if c.PublicKeySHA256 == "" || c.PublicKeySHA256 != k.PublicKeySHA256 {
			t.Errorf("%s: certificate %q and key %q do not pair", tk.name, c.PublicKeySHA256, k.PublicKeySHA256)
		}
		if c.KeyAlgorithm != k.Algorithm || c.KeySize != k.SizeBits || c.Curve != k.Curve {
			t.Errorf("%s: cert says %s/%d/%s, key says %s/%d/%s", tk.name, c.KeyAlgorithm, c.KeySize, c.Curve, k.Algorithm, k.SizeBits, k.Curve)
		}
	}
	// And a different key must not pair.
	keys := keyTestKeys(t)
	c, _ := ParseCertificateDER(keyTestSelfSigned(t, keys[0].priv, "x"))
	other, _ := x509.MarshalPKCS8PrivateKey(keys[1].priv)
	k, _ := ParsePrivateKeyDER(other)
	if c.PublicKeySHA256 == k.PublicKeySHA256 {
		t.Error("two different keys produced the same PublicKeySHA256")
	}
}

func TestParsePrivateKeyDER_X25519(t *testing.T) {
	// crypto/ecdh keys marshal to PKCS#8 too.
	priv, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	der, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil {
		t.Fatal(err)
	}
	k, ok := ParsePrivateKeyDER(der)
	if !ok || k.Algorithm != "X25519" || k.SizeBits != 256 || k.PublicKeySHA256 != keyTestSPKIHash(t, priv.Public()) {
		t.Errorf("X25519: %+v", k)
	}
	keyAssertNoLeak(t, "x25519", k, priv.Bytes(), der)
}

// keyTestAlg is an AlgorithmIdentifier with optional parameters.
type keyTestAlg struct {
	OID    asn1.ObjectIdentifier
	Params asn1.RawValue `asn1:"optional"`
}

func keyTestMarshal(t testing.TB, v any) []byte {
	t.Helper()
	b, err := asn1.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func keyTestRaw(b []byte) asn1.RawValue { return asn1.RawValue{FullBytes: b} }

func keyTestRandom(n int) []byte {
	b := make([]byte, n)
	_, _ = rand.Read(b)
	return b
}

// keyTestEPKI builds an EncryptedPrivateKeyInfo with arbitrary ciphertext.
func keyTestEPKI(t testing.TB, alg keyTestAlg, ciphertext []byte) []byte {
	return keyTestMarshal(t, struct {
		Alg  keyTestAlg
		Data []byte
	}{alg, ciphertext})
}

func keyTestPBES2(t testing.TB, kdf keyTestAlg, cipher asn1.ObjectIdentifier) keyTestAlg {
	iv := keyTestMarshal(t, keyTestRandom(16))
	params := keyTestMarshal(t, struct{ KDF, Enc keyTestAlg }{kdf, keyTestAlg{cipher, keyTestRaw(iv)}})
	return keyTestAlg{keyMustOID(keyOIDPBES2), keyTestRaw(params)}
}

func TestParsePrivateKeyDER_EncryptedPKCS8(t *testing.T) {
	salt := keyTestRandom(16)
	aes256 := keyMustOID("2.16.840.1.101.3.4.1.42")
	aes128 := keyMustOID("2.16.840.1.101.3.4.1.2")
	des3 := keyMustOID("1.2.840.113549.3.7")
	hmac256 := keyTestAlg{OID: keyMustOID("1.2.840.113549.2.9"), Params: asn1.NullRawValue}

	pbkdf2 := func(iter int, prf *keyTestAlg) keyTestAlg {
		var p []byte
		if prf == nil {
			p = keyTestMarshal(t, struct {
				Salt []byte
				Iter int
			}{salt, iter})
		} else {
			p = keyTestMarshal(t, struct {
				Salt []byte
				Iter int
				PRF  keyTestAlg
			}{salt, iter, *prf})
		}
		return keyTestAlg{keyMustOID(keyOIDPBKDF2), keyTestRaw(p)}
	}
	scrypt := keyTestAlg{keyMustOID(keyOIDScrypt), keyTestRaw(keyTestMarshal(t, struct {
		Salt    []byte
		N, R, P int
	}{salt, 16384, 8, 1}))}
	pbes1 := func(oid string) keyTestAlg {
		return keyTestAlg{keyMustOID(oid), keyTestRaw(keyTestMarshal(t, struct {
			Salt []byte
			Iter int
		}{salt[:8], 2048}))}
	}

	cases := []struct {
		name string
		alg  keyTestAlg
		want string
	}{
		{"pbkdf2-sha256-aes256", keyTestPBES2(t, pbkdf2(2048, &hmac256), aes256), "PBES2 (PBKDF2-HMAC-SHA256, 2048 iterations, AES-256-CBC)"},
		{"pbkdf2-default-prf", keyTestPBES2(t, pbkdf2(100000, nil), aes128), "PBES2 (PBKDF2-HMAC-SHA1, 100000 iterations, AES-128-CBC)"},
		{"pbkdf2-3des", keyTestPBES2(t, pbkdf2(2048, &hmac256), des3), "PBES2 (PBKDF2-HMAC-SHA256, 2048 iterations, DES-EDE3-CBC)"},
		{"scrypt", keyTestPBES2(t, scrypt, aes256), "PBES2 (scrypt N=16384 r=8 p=1, AES-256-CBC)"},
		{"pbes1-md5-des", pbes1("1.2.840.113549.1.5.3"), "pbeWithMD5AndDES-CBC (2048 iterations)"},
		{"pkcs12-3des", pbes1("1.2.840.113549.1.12.1.3"), "pbeWithSHA1And3-KeyTripleDES-CBC (2048 iterations)"},
	}
	for _, c := range cases {
		ciphertext := keyTestRandom(1200)
		der := keyTestEPKI(t, c.alg, ciphertext)
		for _, in := range []struct {
			how string
			k   PrivateKey
			ok  bool
		}{
			{"der", func() PrivateKey { k, _ := ParsePrivateKeyDER(der); return k }(), true},
			{"pem", func() PrivateKey {
				pc := ParsePEMFile(keyTestPEM("ENCRYPTED PRIVATE KEY", der), PEMLimits{})
				if len(pc.PrivateKeys) != 1 {
					t.Fatalf("%s: pem gave %d keys", c.name, len(pc.PrivateKeys))
				}
				return pc.PrivateKeys[0]
			}(), true},
		} {
			k := in.k
			label := c.name + "/" + in.how
			if k.Format != KeyFormatPKCS8 || k.Encrypted == nil || !*k.Encrypted {
				t.Errorf("%s: format=%q encrypted=%v", label, k.Format, k.Encrypted)
			}
			if k.Encryption != c.want {
				t.Errorf("%s: Encryption = %q, want %q", label, k.Encryption, c.want)
			}
			if k.Algorithm != "" || k.PublicKeySHA256 != "" {
				t.Errorf("%s: claimed to know algorithm %q / hash %q of an encrypted key", label, k.Algorithm, k.PublicKeySHA256)
			}
			if k.Unknown != "encrypted; algorithm not readable without the passphrase" {
				t.Errorf("%s: Unknown = %q", label, k.Unknown)
			}
			keyAssertNoLeak(t, label, k, ciphertext, salt)
		}
	}
}

// keyTestOneAsymmetricKey builds a PKCS#8 key for an algorithm the standard
// library does not implement, from arbitrary bytes.
func keyTestOneAsymmetricKey(t testing.TB, oid string, priv, pub []byte) []byte {
	alg := keyTestAlg{OID: keyMustOID(oid)}
	privOctets := keyTestMarshal(t, priv) // an OCTET STRING inside the privateKey OCTET STRING, as ML-DSA's seed choice is
	if pub == nil {
		return keyTestMarshal(t, struct {
			Version int
			Alg     keyTestAlg
			Key     []byte
		}{0, alg, privOctets})
	}
	return keyTestMarshal(t, struct {
		Version int
		Alg     keyTestAlg
		Key     []byte
		Pub     asn1.BitString `asn1:"tag:1"`
	}{1, alg, privOctets, asn1.BitString{Bytes: pub, BitLength: 8 * len(pub)}})
}

func TestParsePrivateKeyDER_PostQuantumByOID(t *testing.T) {
	cases := []struct {
		oid, want string
		pubLen    int
	}{
		{"2.16.840.1.101.3.4.3.17", "ML-DSA-44", 1312},
		{"2.16.840.1.101.3.4.3.18", "ML-DSA-65", 1952},
		{"2.16.840.1.101.3.4.3.19", "ML-DSA-87", 2592},
		{"2.16.840.1.101.3.4.4.2", "ML-KEM-768", 1184},
		{"2.16.840.1.101.3.4.3.20", "SLH-DSA-SHA2-128s", 32},
		{"1.3.101.113", "Ed448", 57},
		{"1.3.101.111", "X448", 56},
	}
	for _, c := range cases {
		priv := keyTestRandom(32)
		// v1: no public key stored, so none can be derived.
		k, ok := ParsePrivateKeyDER(keyTestOneAsymmetricKey(t, c.oid, priv, nil))
		if !ok || k.Algorithm != c.want || k.Format != KeyFormatPKCS8 {
			t.Errorf("%s v1: %+v", c.want, k)
		}
		if k.PublicKeySHA256 != "" || k.Unknown != "public key not stored in the file; not derived" {
			t.Errorf("%s v1: hash %q with Unknown %q", c.want, k.PublicKeySHA256, k.Unknown)
		}
		if strings.HasPrefix(c.want, "ML-") && k.SizeBits != 0 {
			t.Errorf("%s: SizeBits = %d, want 0 (the parameter set is in the name)", c.want, k.SizeBits)
		}
		keyAssertNoLeak(t, c.want+" v1", k, priv)

		// v2: the stored public key gives the hash.
		pub := keyTestRandom(c.pubLen)
		spki := keyTestMarshal(t, struct {
			Alg keyTestAlg
			Pub asn1.BitString
		}{keyTestAlg{OID: keyMustOID(c.oid)}, asn1.BitString{Bytes: pub, BitLength: 8 * len(pub)}})
		sum := sha256.Sum256(spki)
		k, ok = ParsePrivateKeyDER(keyTestOneAsymmetricKey(t, c.oid, priv, pub))
		if !ok || k.Algorithm != c.want || k.PublicKeySHA256 != hex.EncodeToString(sum[:]) || k.Unknown != "" {
			t.Errorf("%s v2: %+v", c.want, k)
		}
		keyAssertNoLeak(t, c.want+" v2", k, priv)
	}
	k, ok := ParsePrivateKeyDER(keyTestOneAsymmetricKey(t, "1.2.3.4.5", keyTestRandom(32), nil))
	if !ok || k.Algorithm != "" || !strings.Contains(k.Unknown, "1.2.3.4.5") {
		t.Errorf("unknown OID: %+v", k)
	}
}

// DSA: the legacy structure stores y; PKCS#8 stores only x, from which y is
// computed. Both must give the same public key hash.
func TestParsePrivateKeyDER_DSA(t *testing.T) {
	p, _ := rand.Prime(rand.Reader, 2048)
	q, _ := rand.Prime(rand.Reader, 256)
	g, _ := rand.Int(rand.Reader, p)
	x, _ := rand.Int(rand.Reader, q)
	y := new(big.Int).Exp(g, x, p)

	legacy := keyTestMarshal(t, struct{ V, P, Q, G, Y, X *big.Int }{big.NewInt(0), p, q, g, y, x})
	params := keyTestMarshal(t, struct{ P, Q, G *big.Int }{p, q, g})
	pkcs8 := keyTestMarshal(t, struct {
		Version int
		Alg     keyTestAlg
		Key     []byte
	}{0, keyTestAlg{keyMustOID(keyOIDDSA), keyTestRaw(params)}, keyTestMarshal(t, x)})

	a, ok1 := ParsePrivateKeyDER(legacy)
	b, ok2 := ParsePrivateKeyDER(pkcs8)
	if !ok1 || !ok2 {
		t.Fatal("DSA not recognised")
	}
	if a.Format != KeyFormatDSA || b.Format != KeyFormatPKCS8 || a.Algorithm != "DSA" || b.Algorithm != "DSA" || a.SizeBits != 2048 || b.SizeBits != 2048 {
		t.Errorf("legacy %+v / pkcs8 %+v", a, b)
	}
	if a.PublicKeySHA256 == "" || a.PublicKeySHA256 != b.PublicKeySHA256 {
		t.Errorf("legacy %q and PKCS#8 %q disagree on the public key", a.PublicKeySHA256, b.PublicKeySHA256)
	}
	keyAssertNoLeak(t, "dsa legacy", a, x.Bytes())
	keyAssertNoLeak(t, "dsa pkcs8", b, x.Bytes())

	// x must be below q: an x in [q, p) is refused, not exponentiated.
	aboveQ := keyTestDSAPKCS8(t, p, q, g, new(big.Int).Sub(p, big.NewInt(5)))
	if h, ok := ParsePrivateKeyDER(aboveQ); !ok || h.PublicKeySHA256 != "" || h.Unknown == "" {
		t.Errorf("an x above q was used: %+v", h)
	}
}

func keyTestDSAPKCS8(t testing.TB, p, q, g, x *big.Int) []byte {
	return keyTestMarshal(t, struct {
		Version int
		Alg     keyTestAlg
		Key     []byte
	}{0, keyTestAlg{keyMustOID(keyOIDDSA), keyTestRaw(keyTestMarshal(t, struct{ P, Q, G *big.Int }{p, q, g}))}, keyTestMarshal(t, x)})
}

// The reviewer's input: p = 2^16383+12345, q = 7, g = 3, x = p-5 cost 1.6 s
// per key before the bounds.
func keyTestReviewerDSA(t testing.TB) []byte {
	p := new(big.Int).Lsh(big.NewInt(1), 16383)
	p.Add(p, big.NewInt(12345))
	return keyTestDSAPKCS8(t, p, big.NewInt(7), big.NewInt(3), new(big.Int).Sub(p, big.NewInt(5)))
}

func TestParsePrivateKeyDER_DSAHostileIsCheap(t *testing.T) {
	der := keyTestReviewerDSA(t)
	start := time.Now()
	k, ok := ParsePrivateKeyDER(der)
	if d := time.Since(start); d > 750*time.Millisecond {
		t.Errorf("one hostile DSA key took %v", d)
	}
	if !ok || k.Algorithm != "DSA" || k.PublicKeySHA256 != "" || k.Unknown == "" {
		t.Errorf("hostile DSA: %+v", k)
	}

	// Each bound on its own: a p over 8192 bits, a q over 512 bits, an x not
	// below q. Every one is refused before any exponentiation.
	q512 := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 512), big.NewInt(1))
	p16k := new(big.Int).Add(new(big.Int).Lsh(big.NewInt(1), 16383), big.NewInt(12345))
	p2k := new(big.Int).Add(new(big.Int).Lsh(big.NewInt(1), 2047), big.NewInt(12345))
	q2k := new(big.Int).Sub(p2k, big.NewInt(100))
	for name, in := range map[string][]byte{
		"p too large": keyTestDSAPKCS8(t, p16k, q512, big.NewInt(3), new(big.Int).Sub(q512, big.NewInt(1))),
		"q too large": keyTestDSAPKCS8(t, p2k, q2k, big.NewInt(3), new(big.Int).Sub(q2k, big.NewInt(1))),
		"x not < q":   keyTestDSAPKCS8(t, p2k, big.NewInt(7), big.NewInt(3), new(big.Int).Sub(p2k, big.NewInt(5))),
	} {
		if k, ok := ParsePrivateKeyDER(in); !ok || k.PublicKeySHA256 != "" || k.Unknown == "" {
			t.Errorf("%s: derived anyway: %+v", name, k)
		}
	}

	// 2000 of them in one file.
	block := keyTestPEM("PRIVATE KEY", der)
	file := bytes.Repeat(block, 2000)
	start = time.Now()
	pc := ParsePEMFile(file, PEMLimits{})
	if d := time.Since(start); d > 20*time.Second {
		t.Errorf("2000 hostile DSA keys (%d MiB) took %v", len(file)>>20, d)
	}
	if len(pc.PrivateKeys) != 2000 {
		t.Errorf("%d keys", len(pc.PrivateKeys))
	}

	// The worst case the bounds still allow: an 8192-bit p, a 512-bit q and
	// x just below q. Only keyMaxDerivationsPerFile of them are computed.
	p, _ := new(big.Int).SetString("1"+strings.Repeat("0", 2466), 10) // > 2^8191
	p.Add(p, big.NewInt(1))
	for p.BitLen() > keyMaxDSAPBits {
		p.Rsh(p, 1)
	}
	q := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), keyMaxDSAQBits), big.NewInt(1))
	g := new(big.Int).Sub(p, big.NewInt(2))
	x := new(big.Int).Sub(q, big.NewInt(1))
	worst := keyTestPEM("PRIVATE KEY", keyTestDSAPKCS8(t, p, q, g, x))
	start = time.Now()
	pc = ParsePEMFile(bytes.Repeat(worst, 2000), PEMLimits{})
	if d := time.Since(start); d > 20*time.Second {
		t.Errorf("2000 worst-case DSA keys took %v", d)
	}
	derived := 0
	for _, k := range pc.PrivateKeys {
		if k.PublicKeySHA256 != "" {
			derived++
		} else if !strings.Contains(k.Unknown, "per-file derivation limit") {
			t.Fatalf("an underived key says %q", k.Unknown)
		}
	}
	if derived != keyMaxDerivationsPerFile {
		t.Errorf("%d derivations in one file, want %d", derived, keyMaxDerivationsPerFile)
	}
}

// A 100,000-arc OID must not be repeated into the report.
func TestKeyLongOIDsAreNotRepeated(t *testing.T) {
	long := make(asn1.ObjectIdentifier, 100000)
	long[0], long[1] = 1, 2
	for i := 2; i < len(long); i++ {
		long[i] = 1
	}
	short := keyMustOID("1.2.3.4.5")
	check := func(label string, v any) {
		t.Helper()
		blob, _ := json.Marshal(v)
		if len(blob) > 4096 || bytes.Contains(blob, []byte("1.1.1.1.1.1.1.1")) {
			t.Errorf("%s: the long OID reached the record (%d bytes)", label, len(blob))
		}
	}
	k, _ := ParsePrivateKeyDER(keyTestMarshal(t, struct {
		Version int
		Alg     keyTestAlg
		Key     []byte
	}{0, keyTestAlg{OID: long}, keyTestMarshal(t, []byte{1})}))
	if k.Unknown != "unrecognised key algorithm" {
		t.Errorf("long key OID: Unknown %q", k.Unknown)
	}
	check("pkcs8", k)
	k, _ = ParsePrivateKeyDER(keyTestMarshal(t, struct {
		Version int
		Alg     keyTestAlg
		Key     []byte
	}{0, keyTestAlg{OID: short}, keyTestMarshal(t, []byte{1})}))
	if k.Unknown != "unrecognised key algorithm 1.2.3.4.5" {
		t.Errorf("short key OID: Unknown %q", k.Unknown)
	}
	e, _ := ParsePrivateKeyDER(keyTestEPKI(t, keyTestAlg{OID: long}, keyTestRandom(32)))
	if e.Encryption != "unrecognised scheme" {
		t.Errorf("long scheme OID: %q", e.Encryption)
	}
	check("epki", e)
	e, _ = ParsePrivateKeyDER(keyTestEPKI(t, keyTestPBES2(t, keyTestAlg{OID: long}, long), keyTestRandom(32)))
	if e.Encryption != "PBES2 (unrecognised KDF, unrecognised cipher)" {
		t.Errorf("long KDF/cipher OIDs: %q", e.Encryption)
	}
	check("pbes2", e)
	c, err := ParseCertificateDER(keyTestHandCertOID(t, long))
	if err != nil {
		t.Fatal(err)
	}
	if c.SignatureAlg != "unrecognised" || c.KeyAlgorithm != "" {
		t.Errorf("long signature OID: %q / %q", c.SignatureAlg, c.KeyAlgorithm)
	}
	c.CertificatePEM = "" // the certificate itself is public and carries the OID
	check("certificate", c)
}

func TestParsePrivateKeyDER_RejectsNonKeys(t *testing.T) {
	keys := keyTestKeys(t)
	cert := keyTestSelfSigned(t, keys[2].priv, "not a key")
	for name, b := range map[string][]byte{
		"empty":       nil,
		"garbage":     []byte("hello world"),
		"certificate": cert,
		"integer":     keyTestMarshal(t, 5),
		"spki":        func() []byte { b, _ := x509.MarshalPKIXPublicKey(keys[2].priv.Public()); return b }(),
	} {
		if k, ok := ParsePrivateKeyDER(b); ok {
			t.Errorf("%s: taken for a private key: %+v", name, k)
		}
	}
}
